const r=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),read=f=>JSON.parse(fs.readFileSync(f)),active=read(path.join(r,'native-quote-active.json')),dir=path.join(r,'research-cohorts',active.cohort),preparation=read('data/native-quote-preparation-20261004.json');
assert.equal(active.cohort,'baal-quote-history-20261004-v1');assert.equal(sha(fs.readFileSync(path.join(r,'native-quote-active.json'))),preparation.activeHash);assert.equal(sha(fs.readFileSync(path.join(dir,'declaration.json'))),preparation.declarationHash);
