assert(process.argv.slice(2).every(x=>x==='--v2'),'Only the current V2 study is runnable with this source');const revision='v2',output=path.join(dir,'historical-markouts-v2.json');assert(!fs.existsSync(output),'Original evidence retained');
const start=performance.now(),child=spawnSync(nativeExecutable,['quote-markouts','--declaration',path.join(dir,'declaration.json'),'--sources',path.join(dir,'seed.sources.json'),'--workers','8','--out',output],{encoding:'utf8',windowsHide:true,maxBuffer:65536});const wallMs=performance.now()-start;assert.equal(child.status,0,child.stderr);const receipt=JSON.parse(child.stdout),result=read(output),m=result.markouts,graph=[...fs.readFileSync('backend-rust/build.rs','utf8').matchAll(/^\s*"([^"]+)",$/gm)].map(x=>x[1]),h=createHash('sha256'),sourceHashes={};
