const compact=c=>({strategy:c.strategy,parameters:c.parameters,scenario:c.scenario,featurePolicy:c.featurePolicy,boundaryPolicy:c.boundaryPolicy,summary:c.summary,signalDiagnostics:c.signalDiagnostics}),stats=m.cards.map(compact),sensitivity=(m.bookBoundarySensitivityCards??[]).map(compact);
