if(revision==='v2'){const original=read('data/native-quote-markouts-20261004.json');evidence.initialBoundaryCensoredStudy={evidenceHash:sha(fs.readFileSync('data/native-quote-markouts-20261004.json')),engineHash:original.engineHash,binaryHash:original.binaryHash,outputHash:original.outputHash,notOverwritten:true};}
const archive=path.join(r,'native-sources',engineHash);for(const [file,hash]of Object.entries(sourceHashes)){const dest=path.join(archive,file.replace(/^backend-rust\//,'')),b=fs.readFileSync(file);assert.equal(sha(b),hash);fs.mkdirSync(path.dirname(dest),{recursive:true});if(fs.existsSync(dest))assert.equal(sha(fs.readFileSync(dest)),hash);else fs.writeFileSync(dest,b,{flag:'wx'});}
const build=path.join(r,'native-builds',evidence.binaryHash);fs.mkdirSync(build,{recursive:true});for(const file of ['baal-backend.exe','libunwind.dll']){const dest=path.join(build,file),b=fs.readFileSync(path.join(path.dirname(nativeExecutable),file));if(fs.existsSync(dest))assert.equal(sha(fs.readFileSync(dest)),sha(b));else fs.writeFileSync(dest,b,{flag:'wx'});}
