console.log(JSON.stringify({sourceDays:evidence.sourceDays,sourceBytes:evidence.sourceBytes,quoteRows:m.quoteRows,candidates:108,diagnosticPaths:m.diagnosticPaths,markets:237,timing:evidence.timing,fallingReboundFeatureRejections:m.fallingReboundFeatureRejections,baseline:stats.filter(c=>c.scenario.id==='baseline_3s'&&c.featurePolicy==='original_self_comparison_v1').map(c=>({id:c.strategy,episodes:c.summary.episodes,observed:c.summary.observed,mean:c.summary.quotedNetMarkout.mean,statuses:c.summary.statusCounts})),profitabilityEstablished:false}));
